import React from 'react';
import { BarChart3, Users, DollarSign, ShoppingCart, Activity } from 'lucide-react';

const Dashboard = () => {
  const stats = [
    {
      title: "Revenu total",
      value: "$54,236",
      change: "+12.5%",
      icon: <DollarSign size={24} />,
      color: "bg-green-500"
    },
    {
      title: "Nouveaux utilisateurs",
      value: "2,543",
      change: "+8.2%",
      icon: <Users size={24} />,
      color: "bg-blue-500"
    },
    {
      title: "Commandes",
      value: "1,847",
      change: "+5.3%",
      icon: <ShoppingCart size={24} />,
      color: "bg-purple-500"
    },
    {
      title: "Performance",
      value: "89.2%",
      change: "+2.4%",
      icon: <Activity size={24} />,
      color: "bg-orange-500"
    }
  ];

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-neutral-900 dark:text-white mb-2">
          Tableau de bord
        </h1>
        <p className="text-neutral-600 dark:text-neutral-400">
          Bienvenue sur votre tableau de bord. Voici un aperçu de vos performances.
        </p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {stats.map((stat, index) => (
          <div 
            key={index} 
            className="bg-white dark:bg-neutral-800 rounded-xl p-6 shadow-lg border border-neutral-200 dark:border-neutral-700"
          >
            <div className="flex items-center justify-between mb-4">
              <div className={`p-3 rounded-lg ${stat.color} text-white`}>
                {stat.icon}
              </div>
              <span className="text-sm font-medium text-green-600 dark:text-green-400">
                {stat.change}
              </span>
            </div>
            <h3 className="text-2xl font-bold text-neutral-900 dark:text-white mb-1">
              {stat.value}
            </h3>
            <p className="text-neutral-600 dark:text-neutral-400 text-sm">
              {stat.title}
            </p>
          </div>
        ))}
      </div>

      {/* Content Sections */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Chart Section */}
        <div className="bg-white dark:bg-neutral-800 rounded-xl p-6 shadow-lg border border-neutral-200 dark:border-neutral-700">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-xl font-semibold text-neutral-900 dark:text-white">
              Aperçu des performances
            </h2>
            <BarChart3 className="text-neutral-400" size={24} />
          </div>
          <div className="h-64 flex items-center justify-center border-2 border-dashed border-neutral-300 dark:border-neutral-700 rounded-lg">
            <p className="text-neutral-500 dark:text-neutral-400">
              Graphique des performances
            </p>
          </div>
        </div>

        {/* Recent Activity */}
        <div className="bg-white dark:bg-neutral-800 rounded-xl p-6 shadow-lg border border-neutral-200 dark:border-neutral-700">
          <h2 className="text-xl font-semibold text-neutral-900 dark:text-white mb-6">
            Activité récente
          </h2>
          <div className="space-y-4">
            {[
              { user: "Jean Dupont", action: "a créé une nouvelle commande", time: "Il y a 2 minutes" },
              { user: "Marie Curie", action: "a mis à jour son profil", time: "Il y a 15 minutes" },
              { user: "Pierre Martin", action: "a téléchargé un fichier", time: "Il y a 1 heure" },
              { user: "Sophie Laurent", action: "a commenté un post", time: "Il y a 2 heures" },
              { user: "Thomas Bernard", action: "a complété une tâche", time: "Il y a 3 heures" }
            ].map((activity, index) => (
              <div key={index} className="flex items-center space-x-3 p-3 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-700/50">
                <div className="w-10 h-10 rounded-full bg-primary-100 dark:bg-primary-900/30 flex items-center justify-center">
                  <span className="font-semibold text-primary-600 dark:text-primary-400">
                    {activity.user.charAt(0)}
                  </span>
                </div>
                <div className="flex-1">
                  <p className="text-sm text-neutral-900 dark:text-white">
                    <span className="font-semibold">{activity.user}</span> {activity.action}
                  </p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400">
                    {activity.time}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Welcome Message */}
      <div className="mt-8 p-6 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-xl text-white">
        <h3 className="text-xl font-bold mb-2">Félicitations ! 🎉</h3>
        <p>Vous avez réussi à vous connecter. Explorez maintenant toutes les fonctionnalités de votre tableau de bord.</p>
      </div>
    </div>
  );
};

export default Dashboard;
